1	/// AD-5 — the one URL builder in `core/`. Maps every operation to
2	/// `{FUNCTIONS_BASE_URL}/<x-cerne-function>/<path-params>` — never the
3	/// literal `openapi.yaml` REST path, which is not a real URL. Path
4	/// parameters are appended as trailing segments, in the same order they
5	/// appear in the contract's path; any literal segment after the last
6	/// parameter (e.g. the `/retry` of `chat.messages.retry`) does not exist in
7	/// the real URL and must not be passed here.
8	class UrlBuilder {
9	  const UrlBuilder(this.baseUrl);
10	
11	  /// `FUNCTIONS_BASE_URL`, loaded via `flutter_dotenv` — never hardcoded.
12	  final String baseUrl;
13	
14	  /// Builds the real request URL for [function] (the operation's
15	  /// `x-cerne-function` name), appending [pathParams] as trailing segments.
16	  String build(String function, [List<String> pathParams = const []]) {
17	    final trimmedBase = baseUrl.replaceAll(RegExp(r'/+$'), '');
18	    final segments = [function, ...pathParams].map(Uri.encodeComponent);
19	    return '$trimmedBase/${segments.join('/')}';
20	  }
21	}
