16	/// The project's single `get_it` instance — exactly one DI container exists
17	/// (architecture spine). Every feature's `registerXFeature()` registers
18	/// through this same `sl`, never a second container.
19	final sl = GetIt.instance;
20	
21	/// Bootstraps core infrastructure: loads `.env`, then registers
22	/// `FlutterSecureStorage`, `Dio` (configured with the header + retry
23	/// interceptors) and `ApiClient` through `sl` — the `dio` +
24	/// `flutter_secure_storage` + `get_it` integration spike this story proves
25	/// before anything else is built on top of it.
26	Future<void> setupCoreDependencies() async {
27	  await dotenv.load(fileName: '.env');
28	
29	  final functionsBaseUrl = dotenv.get('FUNCTIONS_BASE_URL');
30	  final supabaseAnonKey = dotenv.get('SUPABASE_ANON_KEY');
31	
32	  sl.registerLazySingleton<FlutterSecureStorage>(
33	    () => const FlutterSecureStorage(),
34	  );
35	
36	  sl.registerLazySingleton<AccessTokenProvider>(
37	    () => SecureStorageAccessTokenProvider(sl<FlutterSecureStorage>()),
38	  );
39	
40	  sl.registerLazySingleton<UrlBuilder>(() => UrlBuilder(functionsBaseUrl));
41	
42	  // Story 1.5 — `dispose:` wires `SessionExpiryNotifier.dispose()` into
43	  // `get_it`'s own reset lifecycle, same rationale as `SessionRepository`'s
44	  // own registration below. Registration order here is cosmetic, not
45	  // load-bearing: `registerLazySingleton` only builds its instance on first
46	  // `sl<T>()` access, so `ApiClient`'s factory can resolve this dependency
47	  // correctly regardless of which of the two is registered first.
48	  sl.registerLazySingleton<SessionExpiryNotifier>(
49	    () => SessionExpiryNotifierImpl(),
50	    dispose: (notifier) => notifier.dispose(),
51	  );
52	
53	  sl.registerLazySingleton<Dio>(() {
54	    final dio = Dio(
55	      BaseOptions(
56	        // Design note (docs/input is silent on exact numbers): a stalled
57	        // connection must still fail instead of hanging indefinitely.
58	        connectTimeout: const Duration(seconds: 10),
59	        receiveTimeout: const Duration(seconds: 30),
60	        sendTimeout: const Duration(seconds: 30),
61	      ),
62	    );
63	    dio.interceptors.add(
64	      HeaderInterceptor(
65	        anonKey: supabaseAnonKey,
66	        accessTokenProvider: sl<AccessTokenProvider>(),
67	      ),
68	    );
69	    dio.interceptors.add(RetryInterceptor(dio));
70	    return dio;
71	  });
72	
73	  sl.registerLazySingleton<ApiClient>(
74	    () => ApiClient(
75	      dio: sl<Dio>(),
76	      urlBuilder: sl<UrlBuilder>(),
77	      sessionExpiryNotifier: sl<SessionExpiryNotifier>(),
78	    ),
79	  );
80	
81	  registerAuthFeature();
82	  registerVaultFeature();
83	  registerAccountFeature();
84	}
