13	/// Owns the one broadcast `biometricEnabled` stream Story 2.4's AD-14-style
14	/// seam requires. Covers the I/O & Edge-Case Matrix exactly:
15	/// - boot fetch resolves `false`/`true` -> [currentBiometricEnabled]/
16	///   [biometricEnabledStream] updated to that value.
17	/// - boot fetch fails -> swallowed, [currentBiometricEnabled] unchanged.
18	/// - [setBiometricEnabled] -> flips immediately (optimistic), PATCH fires;
19	///   success leaves it flipped, failure reverts it and returns `Left`.
20	class AccountSettingsRepositoryImpl implements AccountSettingsRepository {
21	  AccountSettingsRepositoryImpl({
22	    required AccountRemoteDataSource remoteDataSource,
23	  }) : _remoteDataSource = remoteDataSource;
24	
25	  final AccountRemoteDataSource _remoteDataSource;
26	  final StreamController<bool> _controller = StreamController<bool>.broadcast();
27	
28	  /// Starts `true` (never `null`, Boundaries) — the single source of truth
29	  /// for both the vault gate and the Configurações toggle.
30	  bool _currentValue = true;
31	
32	  /// Review finding: without this, two overlapping calls — a double-tap
33	  /// toggle, or a boot [fetchBiometricEnabled] resolving while a
34	  /// [setBiometricEnabled] call is still in flight — let a stale call's
35	  /// revert/confirm stomp a newer call's already-settled value, because
36	  /// each call's own PATCH round-trip resolves independently of the
37	  /// others. Mirrors `VaultRepositoryImpl._submitPinGeneration`'s same
38	  /// fix for the exact same class of bug: every call captures the
39	  /// generation current at its OWN start; only the call whose captured
40	  /// generation still matches this field once its PATCH resolves is
41	  /// allowed to mutate [_currentValue]/emit — every other (superseded)
42	  /// call's result is discarded.
43	  int _generation = 0;
44	
45	  @override
46	  bool get currentBiometricEnabled => _currentValue;
47	
48	  @override
49	  Stream<bool> get biometricEnabledStream {
50	    // Same `Stream.multi` replay-to-late-listeners rationale as
51	    // `VaultRepositoryImpl.statusStream`/`SessionRepositoryImpl.
52	    // statusStream`: a listener that subscribes after construction still
53	    // immediately sees the cached current value rather than nothing until
54	    // the next emission.
55	    return Stream<bool>.multi((controller) {
56	      controller.add(_currentValue);
57	      final subscription = _controller.stream.listen(
58	        controller.add,
59	        onError: controller.addError,
60	        onDone: controller.close,
61	      );
62	      controller.onCancel = subscription.cancel;
63	    }, isBroadcast: true);
64	  }
65	
66	  void _emit(bool value) {
67	    // Guards against `dispose()` (wired to `get_it`'s `sl.reset()`) racing
68	    // an in-flight `fetchBiometricEnabled()`/`setBiometricEnabled()` call —
69	    // mirrors `VaultRepositoryImpl._emit`'s own guard.
70	    if (_controller.isClosed) {
71	      return;
72	    }
73	    _currentValue = value;
74	    _controller.add(value);
75	  }
76	
77	  @override
78	  Future<Either<Failure, Unit>> fetchBiometricEnabled() async {
79	    final generation = ++_generation;
80	    final result = await _remoteDataSource.fetchSettings();
81	    return result.match((failure) {
82	      // Swallowed, fire-and-forget like `SessionRepository.
83	      // restoreSession()` — `currentBiometricEnabled` stays exactly as it
84	      // was (I/O matrix: "Boot fetch fails").
85	      return left(failure);
86	    }, (dto) {
87	      // Review finding: a `setBiometricEnabled` call that started after
88	      // this fetch (and has therefore already bumped `_generation`) has
89	      // superseded it — this fetch's now-stale read must not clobber
90	      // whatever that newer call already settled on, and must not report
91	      // success either, since its result was discarded (mirrors
92	      // `setBiometricEnabled`'s own stale-generation branch).
93	      if (generation != _generation) {
94	        return left(
95	          const Failure.malformedResponse(
96	            message: AccountSettingsRepository.supersededMessage,
97	          ),
98	        );
99	      }
100	      _emit(dto.biometricEnabled);
101	      return right(unit);
102	    });
103	  }
104	
105	  @override
106	  Future<Either<Failure, Unit>> setBiometricEnabled(bool enabled) async {
107	    final generation = ++_generation;
108	    final previous = _currentValue;
109	    // Optimistic flip — switches immediately, before the PATCH call below
110	    // even starts (RNF01, <100ms; Boundaries). Always applied: this call
111	    // is, by construction, the newest one at the moment it starts.
112	    _emit(enabled);
113	    final result = await _remoteDataSource.updateBiometricEnabled(enabled);
114	    if (generation != _generation) {
115	      // Review finding: superseded by a newer call (another toggle, or a
116	      // fetch) that started while this PATCH was still in flight — this
117	      // call's own confirm/revert must never run at this point; the
118	      // superseding call owns `_currentValue` from here on.
119	      return left(
120	        const Failure.malformedResponse(
121	          message: AccountSettingsRepository.supersededMessage,
122	        ),
123	      );
124	    }
125	    return result.match((failure) {
126	      // Revert on failure — the caller surfaces `failure.message` inline.
127	      _emit(previous);
128	      return left(failure);
129	    }, (_) => right(unit));
130	  }
131	
132	  @override
133	  Future<void> dispose() async {
134	    await _controller.close();
135	  }
136	}
