 7	/// The account feature's one write call (`account-settings-update`) — the
 8	/// only `/account/settings` endpoint (Boundaries: "no GET endpoint exists").
 9	/// Posts via the shared `ApiClient`, mirroring
10	/// `auth_remote_data_source.dart`'s pattern.
11	class AccountRemoteDataSource {
12	  AccountRemoteDataSource(this._apiClient);
13	
14	  final ApiClient _apiClient;
15	
16	  /// Called with `{}` to read the current settings without changing
17	  /// anything (Boundaries: "`PATCH /account/settings` ... called empty to
18	  /// read").
19	  Future<Either<Failure, AccountSettingsDto>> fetchSettings() =>
20	      _patch(const {});
21	
22	  /// Called with exactly `{"biometricEnabled": enabled}` to write — never
23	  /// `displayName`/`persona` (Epic 8's scope, Boundaries).
24	  Future<Either<Failure, AccountSettingsDto>> updateBiometricEnabled(
25	    bool enabled,
26	  ) => _patch({'biometricEnabled': enabled});
27	
28	  Future<Either<Failure, AccountSettingsDto>> _patch(
29	    Map<String, dynamic> data,
30	  ) async {
31	    final result = await _apiClient.patch(
32	      'account-settings-update',
33	      data: data,
34	    );
35	    return result.flatMap((json) {
36	      try {
37	        final responseData = json['data'] as Map<String, dynamic>;
38	        return right(AccountSettingsDto.fromJson(responseData));
39	      } catch (error) {
40	        // A 200 response that doesn't match the expected shape is a
41	        // client-side parse failure, never a backend-sent code — maps to
42	        // the local-only `malformedResponse` (RNF09: no exception escapes).
43	        return left(Failure.malformedResponse(message: error.toString()));
44	      }
45	    });
46	  }
47	}

